function renderImportedCatalogs(){document.getElementById('frameworkCatalog').innerHTML=standardData.map(x=>libCard([x[1],x[2],x[3],x[0],x[4]],x[0])).join('');document.getElementById('regCatalog').innerHTML=regData.map(x=>libCard([x[0],x[1],x[2],x[3]],'India · '+(indiaStandards.find(r=>r.short_title===x[0])?.jurisdiction||'central/state'))).join('');document.getElementById('controlCatalog').innerHTML=controlData.map(x=>`<article class="libitem" data-libsearch="${libEsc(x.join(' ').toLowerCase())}"><div class="libmeta"><span class="badgepill pill-blue">${libEsc(x[2])}</span></div><h3>${libEsc(x[0])}</h3><p>${libEsc(x[1])}</p><span class="libsource">Practice starter · ${libEsc(x[3])}</span></article>`).join('');document.getElementById('esgRows').innerHTML=esgData.map(x=>`<tr data-libsearch="${libEsc(x.join(' ').toLowerCase())}"><td><div class="riskname">${libEsc(x[0])}</div><div class="riskid">${libEsc(x[5])}</div></td><td>${libEsc(x[1])}</td><td>${libEsc(x[2])}</td><td>${libEsc(x[3])}</td><td>${libEsc(x[4])}</td></tr>`).join('');addLibCardHandlers();document.querySelectorAll('#esgRows tr').forEach(row=>row.onclick=()=>{const title=row.querySelector('.riskname')?.textContent;openLibraryRecord(esgData.find(x=>x[0]===title)?.[5])});renderLibraryMap();filterLib()}
