const baseRiskProfile=riskProfile;riskProfile=function(title,area){const t=riskTemplates.find(x=>x.title.toLowerCase()===String(title).toLowerCase());if(!t)return baseRiskProfile(title,area);const p=practiceById.get(t.practice);const old=baseRiskProfile(title,area);return{scenario:t.description,prevention:(p?.key_controls||'Assign a competent owner; define a preventive control and monitoring frequency.').split('|').map(x=>x.trim()).filter(Boolean).slice(0,5),mitigation:old.mitigation,evidence:(p?.data_fields||'Owner, action, review date, approval and evidence').split('|').map(x=>x.trim()).filter(Boolean).slice(0,5)}};
const baseDisplayRisk=displayRisk;displayRisk=function(r){const t=riskTemplates.find(x=>x.title.toLowerCase()===r.name.toLowerCase()),p=t&&practiceById.get(t.practice);const prof=riskProfile(r.name,r.area);const refs=t?t.standards.map(id=>libraryById.get(id)).filter(Boolean):[];showDetail(r.name,'Risk record · '+r.id,`<div class="detailgrid">${box('Operational area',libEsc(r.area))}${box('Inherent rating',libEsc(r.inherent))}${box('Residual rating',libEsc(r.rating+' · '+r.score+'/25'))}${box('Risk owner',libEsc(r.owner))}${box('Next review',libEsc(r.reviewDate||r.date))}${box('Treatment status',libEsc(r.status))}</div><h4>Risk scenario and business impact</h4><p>${libEsc(r.description||prof.scenario)}</p><h4>Preventive controls</h4>${bullets(prof.prevention.map(libEsc))}<h4>Mitigation and recovery</h4>${bullets(prof.mitigation.map(libEsc))}<h4>Mapped practice and standards</h4>${p?`<p><b>${libEsc(p.title)}</b> · ${libEsc(p.area)} — ${libEsc(p.summary)}</p>`:''}<div class="mapchips">${refs.map(x=>`<button class="mapchip" data-open-record="${libEsc(x.id)}">${libEsc(x.code)} · ${libEsc(x.short_title)}</button>`).join('')}</div><h4>Evidence / data fields</h4>${bullets([...(prof.evidence||[]),...(p?.data_fields||'').split('|').map(x=>x.trim()).filter(Boolean)].map(libEsc))}<div class="detailbox"><b>AI and data note</b>AI suggestions are contextual prototype guidance. Validate controls, ratings, owners, and obligations with plant records and competent reviewers.</div>`);document.querySelectorAll('#detailBody [data-open-record]').forEach(b=>b.onclick=()=>openLibraryRecord(b.dataset.openRecord))};
document.getElementById('saveRisk').onclick=()=>{const title=document.getElementById('newRiskName').value.trim();if(!title){toast('Select a catalog risk or enter a title.');return}const score=Number(likSel.value)*Number(impSel.value),rating=scoresToRating(score),who=ownerSel.value||'Unassigned',t=riskTemplates.find(x=>x.id===templateSel.value),reviewDate=reviewInput.value||shiftISODate(localISODate(),30);const r={id:'R-'+String(40+risks.length+1).padStart(3,'0'),name:title,area:areaSel.value,inherent:rating,rating,score,likelihood:Number(likSel.value),impact:Number(impSel.value),owner:who,initial:initials(who==='Unassigned'?'U':who),date:new Date(`${reviewDate}T12:00:00`).toLocaleDateString('en-IN',{month:'short',day:'2-digit'}),reviewDate,description:document.getElementById('newRiskDesc').value.trim(),practiceId:t?.practice||'',standardIds:t?.standards||[],status:'Action needed',createdDate:localISODate()};risks.unshift(r);savedRisks.unshift(r);try{localStorage.setItem('forgeGrcCreatedRisksV1',JSON.stringify(savedRisks))}catch{}render();closeModal();go('risks');toast(`Risk ${r.id} created · score ${score}/25`)};
riskRow=function(r,full=false){const safeName=libEsc(r.name),safeArea=libEsc(r.area),safeOwner=libEsc(r.owner),safeId=libEsc(r.id),dateText=libEsc(r.reviewDate||r.date);const ownerHtml=`<span class="owner"><span class="ownerav">${libEsc(r.initial||initials(r.owner))}</span>${safeOwner}</span>`;return full?`<tr data-rating="${libEsc(r.rating)}" data-area="${safeArea}" data-search="${libEsc((r.id+r.name+r.area+r.owner).toLowerCase())}"><td class="riskid">${safeId}</td><td><div class="riskname">${safeName}</div><div class="riskarea">Residual score ${Number(r.score)||0} / 25</div></td><td>${safeArea}</td><td>${badge(libEsc(r.inherent))}</td><td>${badge(libEsc(r.rating))} <span class="risk-score">${Number(r.score)||0}</span></td><td>${ownerHtml}</td><td>${dateText}</td><td>${badge(libEsc(r.status))}</td></tr>`:`<tr><td><div class="riskname">${safeName}</div><div class="riskid">${safeId} · ${safeArea}</div></td><td>${safeArea}</td><td>${badge(libEsc(r.rating))} <span class="risk-score">${Number(r.score)||0}</span></td><td>${ownerHtml}</td><td>${dateText}</td></tr>`};renderImportedCatalogs();
